INSERT IGNORE INTO knowledge_documents (id,title,document_type,content,tags,uploaded_by) VALUES
(5,'Authentication Service Architecture','document','The authentication service issues JWT access tokens valid for 15 minutes and refresh tokens valid for 7 days.\n\nTokens are signed with RS256. The private key is stored in the secrets manager and rotated every 90 days. Public keys are served at the JWKS endpoint.\n\nProtected endpoints validate the signature, expiry and audience claim. Failed validation returns HTTP 401 with a generic error body.','JWT, authentication, architecture, tokens',2),
(6,'Release and Deployment Runbook','guide','Releases are cut from the main branch every second Thursday after QA sign-off.\n\nDeployment steps: run the migration job, deploy the backend to staging, run the smoke suite, then promote to production. Roll back by redeploying the previous image tag.\n\nThe on-call engineer must be notified in the engineering channel before every production release.','release, deployment, runbook, operations',2);
